pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 revertAmount) public {
        // Bound the deposit to a reasonable range to avoid overflow and ensure enough funds
        depositAmount = bound(depositAmount, 1, 100 ether);
        revertAmount = bound(revertAmount, 0, depositAmount);

        // Deploy an adversarial callee that always reverts on receiving ETH
        Reverter reverter = new Reverter();

        // Send ETH to the contract so it has a balance to withdraw
        vm.deal(address(c), depositAmount);
        // Update the internal accounting to match the actual balance
        // Since receive is not implemented, we use a low-level call to trigger fallback which increments depositsCount
        (bool s,) = address(c).call{value: 0}("");
        require(s);

        // Record owner's balance before withdrawAll and sendMoney
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;

        // Owner calls withdrawAll (should withdraw full contract balance in correct version, 0 in buggy)
        vm.prank(owner);
        c.withdrawAll();

        // Owner then sends all remaining ETH to the reverting callee via sendMoney
        // This call will revert, but the sent ETH will be returned to the contract (or never sent in the buggy case)
        vm.prank(owner);
        try c.sendMoney(address(reverter), address(c).balance, "") {} catch {}

        // Finally, owner withdraws whatever is left in the contract
        vm.prank(owner);
        c.withdrawAll();

        // Assert: In the correct version, the owner's balance increases by the full depositAmount
        // In the buggy version, the first withdrawAll withdraws 0, so the owner ends up with less
        assertEq(owner.balance - ownerBalanceBefore, depositAmount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

