pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // amount must be strictly less than balance to prevent arithmetic underflow in balance check
        vm.assume(amount < address(c).balance);
        // Deploy an adversarial callee that always reverts on receiving Ether via callback
        Reverter reverter = new Reverter();
        // Fund the contract to have Ether to send
        vm.deal(address(c), 10 ether);
        bool success = true;
        // Wrap the call in try/catch to capture whether sendMoney reverted or not
        try c.sendMoney(address(reverter), amount, "") {
            success = true;
        } catch {
            success = false;
        }
        // Property: sendMoney to a reverting callee must revert (success == false).
        // The reference reverts because it checks _s and reverts on call failure.
        // The mutant does not revert, so success will be true.
        assertTrue(!success);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
